<?php
if(!defined('ABSPATH'))exit;
class Studio_Documents{
 public static function upload($patient_id){if(!current_user_can(Studio_Roles::CAP_MANAGE_DOCUMENTS))wp_die('Accesso negato');check_admin_referer('studio_upload_document_'.$patient_id);if(empty($_FILES['clinical_document']['tmp_name']))return;$file=$_FILES['clinical_document'];$check=wp_check_filetype_and_ext($file['tmp_name'],$file['name'],array('pdf'=>'application/pdf'));if($check['ext']!=='pdf'||$check['type']!=='application/pdf')wp_die('Sono ammessi solo documenti PDF validi.');$u=wp_upload_dir();$dir=$u['basedir'].'/studio-professionale-docs/patient-'.$patient_id;wp_mkdir_p($dir);$name=wp_unique_filename($dir,sanitize_file_name($file['name']));$path=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$path))wp_die('Caricamento non riuscito.');global $wpdb;$wpdb->insert(Studio_DB::table('documenti'),array('paziente_id'=>$patient_id,'nome_file'=>$name,'percorso'=>$path,'mime'=>'application/pdf','descrizione'=>sanitize_text_field($_POST['document_description']??''),'caricato_da'=>get_current_user_id(),'data_caricamento'=>current_time('mysql')));Studio_Security::audit('upload_documento','paziente',$patient_id,array('file'=>$name));}
 public static function delete($id,$patient_id){if(!current_user_can(Studio_Roles::CAP_MANAGE_DOCUMENTS))wp_die('Accesso negato');check_admin_referer('studio_delete_document_'.$id);global $wpdb;$d=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Studio_DB::table('documenti').' WHERE id=%d AND paziente_id=%d',$id,$patient_id));if($d){if(file_exists($d->percorso))@unlink($d->percorso);$wpdb->delete(Studio_DB::table('documenti'),array('id'=>$id));Studio_Security::audit('delete_documento','paziente',$patient_id,array('file'=>$d->nome_file));}}
 public static function download($id,$patient_id){if(!current_user_can(Studio_Roles::CAP_MANAGE_DOCUMENTS))wp_die('Accesso negato');check_admin_referer('studio_download_document_'.$id);global $wpdb;$d=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Studio_DB::table('documenti').' WHERE id=%d AND paziente_id=%d',$id,$patient_id));if(!$d||!file_exists($d->percorso))wp_die('Documento non trovato');header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.basename($d->nome_file).'"');readfile($d->percorso);exit;}
}
